                                     'json_valid(new.attempt_audit_tool_events_json) then '
                                     "(json_type(new.attempt_audit_tool_events_json) is not 'array' or "
                                     'exists(select 1 from json_each(new.attempt_audit_tool_events_json) e '
                                     "where case when e.type='object' then (json_extract(e.value,'$.tool') "
                                     "is not 'audit_review' or json_extract(e.value,'$.result') is not "
                                     "'queued' or json_remove(e.value,'$.tool','$.result')<>'{}') else 1 "
                                     "end)) else 1 end) begin select raise(abort,'invalid reply audit "
                                     "markers'); end",
